// @studio/contracts — tier-2 ALLOWED engine-command ids (round-12 "Tool catalog v3").
//
// The machine-derived allowlist the whole product validates generic engine
// command proposals against (research/round12-design.md, 12-w2-a5 §6 Option B):
// generated by scripts/extract-engine-registry.mjs from the vendored engine's
// `cmd!` registrations, minus every denied class (app chrome, filesystem, code
// exec, render-output writers, destructive ids, path-like params — see the
// extractor header). This module intentionally imports ONLY the ids artifact
// (~10 KB): the FULL catalog (params docs, deny tags) is gateway-tier data and
// never rides the browser bundle — apps/web reaches this via the
// @studio/api-client re-export seam, exactly like isAgentCommand (F-6).
//
// Tier split:
//   * THIS module (barrel-exported): ids + membership — client gates, plan-card
//     counts, anything browser-facing.
//   * ./engine-catalog.js (subpath `@studio/contracts/catalog`): the full
//     ENGINE_COMMAND_CATALOG + ENGINE_CATALOG_DIGEST — gateway-only.

import allowedIdsJson from "./generated/allowed-command-ids.json" with { type: "json" };

/**
 * The ALLOWED engine command ids (sorted, frozen). Subset of the live registry
 * at the vendored engine pin; regenerated by the extractor on pin bumps.
 */
export const ALLOWED_COMMAND_IDS: readonly string[] = Object.freeze(
  allowedIdsJson satisfies readonly string[],
);

const ALLOWED_COMMAND_ID_SET: ReadonlySet<string> = new Set(ALLOWED_COMMAND_IDS);

/** `true` when `id` is an allowed (non-denied, batchable) engine command id. */
export function isAllowedEngineCommand(id: string): boolean {
  return ALLOWED_COMMAND_ID_SET.has(id);
}

/** Size of {@link ALLOWED_COMMAND_IDS} (pinned by the contracts tests). */
export const ALLOWED_COMMAND_COUNT = ALLOWED_COMMAND_IDS.length;
